        impl < D : Deps > DepGraphData < D > { # [doc = " Try to mark a node index for the node dep_node."] # [doc = ""] # [doc = " A node will have an index, when it's already been marked green, or when we can mark it"] # [doc = " green. This function will mark the current task as a reader of the specified node, when"] # [doc = " a node index can be found for that node."] pub (crate) fn try_mark_green < Qcx : QueryContext < Deps = D > > (& self , qcx : Qcx , dep_node : & DepNode ,) -> Option < (SerializedDepNodeIndex , DepNodeIndex) > { debug_assert ! (! qcx . dep_context () . is_eval_always (dep_node . kind)) ; let prev_index = self . previous . node_to_index_opt (dep_node) ? ; match self . colors . get (prev_index) { Some (DepNodeColor :: Green (dep_node_index)) => Some ((prev_index , dep_node_index)) , Some (DepNodeColor :: Red) => None , None => { self . try_mark_previous_green (qcx , prev_index , dep_node , None) . map (| dep_node_index | (prev_index , dep_node_index)) } } } # [instrument (skip (self , qcx , parent_dep_node_index , frame) , level = "debug")] fn try_mark_parent_green < Qcx : QueryContext < Deps = D > > (& self , qcx : Qcx , parent_dep_node_index : SerializedDepNodeIndex , frame : Option < & MarkFrame < '_ > > ,) -> Option < () > { let dep_dep_node_color = self . colors . get (parent_dep_node_index) ; let dep_dep_node = & self . previous . index_to_node (parent_dep_node_index) ; match dep_dep_node_color { Some (DepNodeColor :: Green (_)) => { debug ! ("dependency {dep_dep_node:?} was immediately green") ; return Some (()) ; } Some (DepNodeColor :: Red) => { debug ! ("dependency {dep_dep_node:?} was immediately red") ; return None ; } None => { } } if ! qcx . dep_context () . is_eval_always (dep_dep_node . kind) { debug ! ("state of dependency {:?} ({}) is unknown, trying to mark it green" , dep_dep_node , dep_dep_node . hash ,) ; let node_index = self . try_mark_previous_green (qcx , parent_dep_node_index , dep_dep_node , frame) ; if node_index . is_some () { debug ! ("managed to MARK dependency {dep_dep_node:?} as green") ; return Some (()) ; } } debug ! ("trying to force dependency {dep_dep_node:?}") ; if ! qcx . dep_context () . try_force_from_dep_node (* dep_dep_node , parent_dep_node_index , frame) { debug ! ("dependency {dep_dep_node:?} could not be forced") ; return None ; } let dep_dep_node_color = self . colors . get (parent_dep_node_index) ; match dep_dep_node_color { Some (DepNodeColor :: Green (_)) => { debug ! ("managed to FORCE dependency {dep_dep_node:?} to green") ; return Some (()) ; } Some (DepNodeColor :: Red) => { debug ! ("dependency {dep_dep_node:?} was red after forcing") ; return None ; } None => { } } if let None = qcx . dep_context () . sess () . dcx () . has_errors_or_delayed_bugs () { panic ! ("try_mark_previous_green() - Forcing the DepNode should have set its color") } debug ! ("dependency {dep_dep_node:?} resulted in compilation error") ; return None ; } # [doc = " Try to mark a dep-node which existed in the previous compilation session as green."] # [instrument (skip (self , qcx , prev_dep_node_index , frame) , level = "debug")] fn try_mark_previous_green < Qcx : QueryContext < Deps = D > > (& self , qcx : Qcx , prev_dep_node_index : SerializedDepNodeIndex , dep_node : & DepNode , frame : Option < & MarkFrame < '_ > > ,) -> Option < DepNodeIndex > { let frame = MarkFrame { index : prev_dep_node_index , parent : frame } ; debug_assert ! (! qcx . dep_context () . is_eval_always (dep_node . kind)) ; debug_assert_eq ! (self . previous . index_to_node (prev_dep_node_index) , * dep_node) ; let prev_deps = self . previous . edge_targets_from (prev_dep_node_index) ; for dep_dep_node_index in prev_deps { self . try_mark_parent_green (qcx , dep_dep_node_index , Some (& frame)) ? ; } let dep_node_index = self . promote_node_and_deps_to_current (prev_dep_node_index) ; debug ! ("successfully marked {dep_node:?} as green") ; Some (dep_node_index) } }
